import subprocess, tempfile, os, hashlib

samples = {
 "secret": "e8008b37b17970377b105efae1e8d5783107",
 "a": "67843e85e28c0d75473ff8fbebd1b81c1e0c",
 "ab": "b679ffebf2b2c4db3905aa0277af6db7d22d",
}

def openssl_aes(key_hex, iv_hex, plaintext_hex, cipher="aes-256-cbc"):
    with tempfile.NamedTemporaryFile(delete=False) as f:
        f.write(bytes.fromhex(plaintext_hex))
        pt = f.name
    with tempfile.NamedTemporaryFile(delete=False) as f:
        ct = f.name
    # ensure key and iv lengths match cipher
    # for aes-256, key 32 bytes (64 hex), iv 16 bytes (32 hex)
    # for aes-128, key 16 bytes
    cmd = ["openssl","enc",f"-{cipher}","-K",key_hex,"-iv",iv_hex,"-in",pt,"-out",ct,"-nopad"]
    # print(cmd)
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode!=0:
        # print(r.stderr)
        pass
    if os.path.exists(ct):
        data = open(ct,"rb").read()
        os.unlink(pt); os.unlink(ct)
        return data.hex()
    else:
        os.unlink(pt)
        if os.path.exists(ct): os.unlink(ct)
        return None

# Try many combos: key derived from password via md5, sha256, etc, plaintext is known string like "CAPS-LOG", "check", "valid"
for pwd, cle in samples.items():
    # try key = sha256(pwd) first 32 bytes
    key256 = hashlib.sha256(pwd.encode()).hexdigest() # 64 hex =32 bytes
    key128 = hashlib.md5(pwd.encode()).hexdigest() # 32 hex
    for pt_str in ["check", "valid", "caps-log", "CAPS", "1234567890123456", "0000000000000000", ""]:
        if pt_str=="":
            pt_hex = "00"*16
        else:
            # pad to 16 bytes with zeros
            b = pt_str.encode()
            if len(b)<16: b = b + b"\x00"*(16-len(b))
            else: b = b[:16]
            pt_hex = b.hex()
        for cipher in ["aes-128-ecb","aes-128-cbc","aes-256-ecb","aes-256-cbc"]:
            if "128" in cipher:
                key = key128
                iv = "00"*32 if "cbc" in cipher else "00"*32
            else:
                key = key256
                iv = "00"*32
            ct = openssl_aes(key, iv, pt_hex, cipher)
            if ct and cle[:32] in ct or (ct and ct[:36]==cle):
                print(f"found {pwd} {cipher} pt {repr(pt_str)} ct {ct} cle {cle}")

# Try with PBKDF2 derived key?
# Also try key = pwd padded/truncated to 16 bytes directly
for pwd, cle in samples.items():
    # key = pwd.ljust(16, '\0')[:16].encode().hex()
    b = pwd.encode()
    if len(b)<16: b = b + b"\x00"*(16-len(b))
    else: b = b[:16]
    key_hex = b.hex()
    for pt_hex in ["00"*16, "ff"*16]:
        ct = openssl_aes(key_hex, "00"*32, pt_hex, "aes-128-ecb")
        if ct and ct[:36]==cle[:36]:
            print(f"direct key {pwd} ct {ct}")

