        ssh_key = git_section.get('ssh-key-path') or git_section.get('ssh_key_path') or config.get('ssh-key-path')
        ssh_pub = git_section.get('ssh-pub-key-path') or git_section.get('ssh_pub_key_path') or config.get('ssh-pub-key-path')
        repo_root = git_section.get('repo-root') or git_section.get('repo_root') or config.get('repo-root')
        if not ssh_key or ssh_key.strip() == "":
            eprint_error("SSH key path can not be empty!")
        ssh_key_exp = expand_path(ssh_key)
        if not os.path.exists(ssh_key_exp):
            eprint_error(f"SSH key does not exist: {ssh_key_exp}")
        if not ssh_pub or ssh_pub.strip() == "":
            eprint_error("SSH public key path can not be empty!")
        ssh_pub_exp = expand_path(ssh_pub)
        if not os.path.exists(ssh_pub_exp):
            eprint_error(f"SSH public key does not exist: {ssh_pub_exp}")
        if repo_root is None or repo_root.strip() == "":
            eprint_error("Git repo root can not be empty!")
        repo_root_exp = expand_path(repo_root)
        repo_abs = os.path.abspath(repo_root_exp)
        log_abs = os.path.abspath(log_dir_expanded)
        try:
            common = os.path.commonpath([repo_abs, log_abs])
            if common != repo_abs:
                eprint_error(f"Error! Git repo root ({repo_abs}) is not parent of log dir ({log_abs})!")
        except ValueError:
            eprint_error(f"Error! Git repo root ({repo_abs}) is not parent of log dir ({log_abs})!")
        git_dir = os.path.join(repo_abs, ".git")
        if not os.path.isdir(git_dir):
            sys.stderr.write(f"Captain's log encountered an error: \n Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '{repo_abs}'\n")
            sys.exit(1)

    cle_path = os.path.join(log_dir_expanded, ".cle")
    cle_exists = os.path.exists(cle_path)
    if cle_exists:
        if password is not None:
            expected = derive_cle(password)
            try:
                actual = open(cle_path, 'rb').read()
            except:
                actual = b""
            if actual != expected:
                eprint_error("Invalid password provided!")
    else:
        if password is not None:
            eprint_error("Password provided for a non encrypted repository!")

    if not os.path.isdir(log_dir_expanded):
        try:
            os.makedirs(log_dir_expanded, exist_ok=True)
        except:
            pass
    scratch_dir = os.path.join(log_dir_expanded, "scratchpads")
    try:
        os.makedirs(scratch_dir, exist_ok=True)
    except:
        pass

    run_tui(log_dir_expanded, log_name_format, sunday_start, first_line_section, sections, config)

