            sys.stderr.write(f"Captain's log encountered an error: \n Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '{repo_abs}'\n")
            sys.exit(1)

    cle_path = os.path.join(log_dir_expanded, ".cle")
    cle_exists = os.path.exists(cle_path)
    if cle_exists:
        if password is not None:
            expected = derive_cle(password)
            try:
                actual = open(cle_path, 'rb').read()
            except:
                actual = b""
            if actual != expected:
                eprint_error("Invalid password provided!")
    else:
        if password is not None:
            eprint_error("Password provided for a non encrypted repository!")

    if not os.path.isdir(log_dir_expanded):
        try:
            os.makedirs(log_dir_expanded, exist_ok=True)
        except:
            pass
    scratch_dir = os.path.join(log_dir_expanded, "scratchpads")
    try:
        os.makedirs(scratch_dir, exist_ok=True)
    except:
        pass

    run_tui(log_dir_expanded, log_name_format, sunday_start, first_line_section, sections, config)

