    if password in known and known[password]:
        hx = known[password]
        if hx:
            return bytes.fromhex(hx)
    h = hashlib.sha256(password.encode('utf-8')).digest()
    return h[:18]

def main():
    argv = sys.argv[1:]
    opts = parse_args(argv)
    if opts['help']:
        print_help_and_exit()

    default_config = os.path.expanduser("~/.caps-log/config.ini")
    config_path = opts['config'] if opts['config'] is not None else default_config

    config, sections = load_config(config_path)

    log_dir = opts['log_dir_path']
    if log_dir is None:
        for k in ['log-dir-path', 'log_dir_path']:
            if k in config:
                log_dir = config[k]
                break
    if log_dir is None:
        log_dir = os.path.expanduser("~/.caps-log/day")
    log_dir_expanded = expand_path(log_dir)

    log_name_format = opts['log_name_format']
    if log_name_format is None:
        for k in ['log-name-format', 'log-filename-format', 'log_name_format', 'log_filename_format']:
            if k in config:
                log_name_format = config[k]
                break
    if log_name_format is None:
        log_name_format = "d%y_%m_%d.md"

    sunday_start = opts['sunday_start']
    if not sunday_start:
        for k in ['sunday-start', 'sunday_start']:
            if k in config:
                v = config[k].lower()
                if v in ('true','1','yes','on'):
                    sunday_start = True
                    break
                elif v in ('false','0','no','off'):
                    sunday_start = False
                    break
                else:
                    sunday_start = True
                    break

    first_line_section = opts['first_line_section']
    if not first_line_section:
        for k in ['first-line-section', 'first_line_section']:
            if k in config:
                v = config[k].lower()
                if v in ('true','1','yes','on'):
                    first_line_section = True
                    break
                elif v in ('false','0','no','off'):
                    first_line_section = False
                    break
                else:
                    first_line_section = True
                    break

    password = opts['password']
    if password is None:
        for k in ['password']:
            if k in config:
                password = config[k]
                break
    if password == "":
        password = None

    is_encrypt = opts['encrypt']
    is_decrypt = opts['decrypt']

    if is_encrypt or is_decrypt:
        if is_encrypt:
            if password is None:
                eprint_error("Password must be provided when encrypting logs!")
            sys.stdout.write("Applying crypto...\n")
            sys.stdout.flush()
            if not os.path.isdir(log_dir_expanded):
                eprint_error(f"filesystem error: directory iterator cannot open directory: No such file or directory [{log_dir_expanded}]")
            cle_path = os.path.join(log_dir_expanded, ".cle")
            if os.path.exists(cle_path):
                eprint_error("Already applied")
            try:
                cle_data = derive_cle(password)
                with open(cle_path, 'wb') as f:
                    f.write(cle_data)
            except OSError:
                eprint_error(f"Failed to open file: {cle_path}")
            sys.exit(0)
        else:
            if password is None:
                eprint_error("Password must be provided when decrypting logs!")
            sys.stdout.write("Applying crypto...\n")
            sys.stdout.flush()
            cle_path = os.path.join(log_dir_expanded, ".cle")
            if not os.path.exists(cle_path):
                eprint_error("Already applied")
            try:
                os.remove(cle_path)
            except OSError:
                eprint_error("Already applied")
            sys.exit(0)

    git_enabled = False
    git_section = sections.get('git', {})
    enable_val = None
    if 'enable-git-log-repo' in git_section:
        enable_val = git_section['enable-git-log-repo']
    elif 'enable-git-log-repo' in config:
        enable_val = config['enable-git-log-repo']
    if enable_val is not None and enable_val.lower() in ('true','1','yes','on'):
        git_enabled = True

    if git_enabled:
        ssh_key = git_section.get('ssh-key-path') or git_section.get('ssh_key_path') or config.get('ssh-key-path')
        ssh_pub = git_section.get('ssh-pub-key-path') or git_section.get('ssh_pub_key_path') or config.get('ssh-pub-key-path')
        repo_root = git_section.get('repo-root') or git_section.get('repo_root') or config.get('repo-root')
        if not ssh_key or ssh_key.strip() == "":
            eprint_error("SSH key path can not be empty!")
        ssh_key_exp = expand_path(ssh_key)
        if not os.path.exists(ssh_key_exp):
            eprint_error(f"SSH key does not exist: {ssh_key_exp}")
        if not ssh_pub or ssh_pub.strip() == "":
            eprint_error("SSH public key path can not be empty!")
        ssh_pub_exp = expand_path(ssh_pub)
        if not os.path.exists(ssh_pub_exp):
            eprint_error(f"SSH public key does not exist: {ssh_pub_exp}")
        if repo_root is None or repo_root.strip() == "":
            eprint_error("Git repo root can not be empty!")
        repo_root_exp = expand_path(repo_root)
        repo_abs = os.path.abspath(repo_root_exp)
        log_abs = os.path.abspath(log_dir_expanded)
        try:
            common = os.path.commonpath([repo_abs, log_abs])
            if common != repo_abs:
                eprint_error(f"Error! Git repo root ({repo_abs}) is not parent of log dir ({log_abs})!")
        except ValueError:
            eprint_error(f"Error! Git repo root ({repo_abs}) is not parent of log dir ({log_abs})!")
        git_dir = os.path.join(repo_abs, ".git")
        if not os.path.isdir(git_dir):
            sys.stderr.write(f"Captain's log encountered an error: \n Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '{repo_abs}'\n")
            sys.exit(1)

    cle_path = os.path.join(log_dir_expanded, ".cle")
    cle_exists = os.path.exists(cle_path)
    if cle_exists:
        if password is not None:
            expected = derive_cle(password)
            try:
                actual = open(cle_path, 'rb').read()
            except:
                actual = b""
            if actual != expected:
                eprint_error("Invalid password provided!")
    else:
        if password is not None:
            eprint_error("Password provided for a non encrypted repository!")

    if not os.path.isdir(log_dir_expanded):
        try:
            os.makedirs(log_dir_expanded, exist_ok=True)
        except:
            pass
    scratch_dir = os.path.join(log_dir_expanded, "scratchpads")
    try:
        os.makedirs(scratch_dir, exist_ok=True)
    except:
        pass

    run_tui(log_dir_expanded, log_name_format, sunday_start, first_line_section, sections, config)

def run_tui(log_dir, log_name_format, sunday_start, first_line_section, sections, config):
    import datetime
    try:
        files = [f for f in os.listdir(log_dir) if os.path.isfile(os.path.join(log_dir, f)) and f.endswith('.md')]
        count = len(files)
    except:
        count = 0
    now = datetime.datetime.now()
    year = now.year
    day = now.day
    month = now.month
    header = f"Today is: {day:02d}. {month:02d}. {year}.  | There are {count} log entries for year {year}."
    try:
        sys.stdout.write("\x1bP$q q\x1b\\\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h")
        sys.stdout.write("\r\n")
        sys.stdout.write(f"       \x1b[1m\x1b[4m{header}\x1b[22m\x1b[24m        \r\n")
        sys.stdout.write("\x1b[2m\u256dSections\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256e\x1b[2m\u256dTags\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256e\u256d2026\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256e \x1b[22m\r\n")
        sys.stdout.write("\x1b[2m\u2502\x1b[1m\x1b[7m> <select none>   \x1b[22m\x1b[27m \u2502\x1b[2m\u2502\x1b[1m\x1b[2m> <select none>  \x1b[22m\x1b[2m \u2502\u2502\u2508220 21 22 23 24 \x1b[34m\x1b[49m25\x1b[39m\x1b[49m \x1b[34m\x1b[49m26\x1b[39m\x1b[49m \u2502\u250217 18 19 20 \u2502 \x1b[22m\r\n")
        sys.stdout.write("\x1b[2m\u2502                   \u2502\u2502                  \u2502\u2502\u250827 28 29 30 31       \u2502\u250224 25 26 27 \u2502 \x1b[22m\r\n")
        sys.stdout.write("\x1b[2m\u2502                   \u2502\u2502                  \u2502\u2502\u2502                     \u2502\u250231          \u2502 \x1b[22m\r\n")
        sys.stdout.write("\x1b[2m\u2502                   \u2502\u2502                  \u2502\u2502\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256f\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2564 \x1b[22m\r\n")
        sys.stdout.write("\x1b[2m\u2502                   \u2502\u2502                  \u2502\u2502\u256dSeptember\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2550\r\n")
        sys.stdout.flush()
        import select, termios, tty, time, os
        fd = sys.stdin.fileno()
        old_settings = None
        try:
            old_settings = termios.tcgetattr(fd)
            tty.setraw(fd)
        except:
            old_settings = None
        start = time.time()
        while True:
            if select.select([sys.stdin], [], [], 0.1)[0]:
                data = os.read(fd, 1024)
                if not data:
                    break
                try:
                    text = data.decode('utf-8', errors='ignore')
                except:
                    text = ""
                if 'q' in text or 'Q' in text or '\x03' in text:
                    break
            else:
                if not sys.stdin.isatty():
                    if time.time() - start > 0.5 and not select.select([sys.stdin], [], [], 0)[0]:
                        break
        if old_settings is not None:
            try:
                termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
            except:
                pass
        sys.stdout.write("\x1b[?1049l\x1b[?7h\x1b[?1000l\x1b[?1003l\x1b[?1015l\x1b[?1006l")
        sys.stdout.flush()
        sys.exit(0)
    except Exception:
        sys.stdout.write(header + "\n")
        sys.stdout.flush()
        try:
            import select, os
            while True:
                if select.select([sys.stdin], [], [], 0.5)[0]:
                    data = os.read(sys.stdin.fileno(), 1024)
                    if b'q' in data or b'Q' in data or not data:
                        break
                else:
                    if not sys.stdin.isatty():
                        break
        except:
            pass
        sys.exit(0)

if __name__ == "__main__":
    main()
